      { $sort: { createdAt: -1 } },
      { $group: { _id: { $cond: [{ $eq: ['$senderId', new mongoose.Types.ObjectId(userId)] }, '$receiverId', '$senderId'] }, lastMessage: { $first: '$$ROOT' } } },
      { $replaceRoot: { newRoot: '$lastMessage' } },
      { $sort: { createdAt: -1 } },
    ]);
    res.json({ success: true, data: conversations });
