const actionColors: Record<string, string> = {
  create: 'green',
  update: 'blue',
  delete: 'red',
};

const actionLabels: Record<string, string> = {
  create: 'إضافة',
  update: 'تعديل',
  delete: 'حذف',
};

// إدارة AudioContext بشكل صحيح
let audioCtx: AudioContext | null = null;

function getAudioContext(): AudioContext | null {
  try {
    if (!audioCtx) {
      audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioCtx.state === 'suspended') {
      audioCtx.resume();
    }
    return audioCtx;
  } catch { return null; }
}

// فتح AudioContext عند أول تفاعل من المستخدم
function unlockAudio(): void {
  const ctx = getAudioContext();
  if (ctx && ctx.state === 'suspended') {
    ctx.resume();
  }
}

function playNotificationSound(): void {
  try {
    const ctx = getAudioContext();
    if (!ctx) return;

    // resume إذا كان معلقاً
    if (ctx.state === 'suspended') {
      ctx.resume();
    }

    const now = ctx.currentTime;

    // نغمتان قصيرتان
    [880, 1320].forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.frequency.value = freq;
      osc.type = 'sine';
      gain.gain.setValueAtTime(0, now + i * 0.15);
      gain.gain.linearRampToValueAtTime(0.3, now + i * 0.15 + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.01, now + i * 0.15 + 0.2);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now + i * 0.15);
      osc.stop(now + i * 0.15 + 0.2);
    });
  } catch { /* ignore */ }
}

export function ActivityBell() {
  const [activities, setActivities] = useState<any[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [open, setOpen] = useState(false);
  const socketRef = useRef<Socket | null>(null);

  const fetchActivities = useCallback(async () => {
    try {
      const res = await activityApi.getAll();
      setActivities(res.data.data || []);
      setUnreadCount(res.data.unreadCount || 0);
    } catch { /* ignore */ }
  }, []);

  useEffect(() => {
    fetchActivities();

    // فتح AudioContext عند أول تفاعل
    const unlock = () => { unlockAudio(); };
    document.addEventListener('click', unlock, { once: true });
    document.addEventListener('keydown', unlock, { once: true });

    // الاتصال بـ socket.io
    const socket = ioClient(SOCKET_URL, {
      transports: ['websocket', 'polling'],
      reconnection: true,
      reconnectionDelay: 1000,
      reconnectionAttempts: Infinity,
    });
    socketRef.current = socket;

    socket.on('connect', () => {
      console.log('📡 Socket.io متصل:', socket.id);
    });

    socket.on('connect_error', (err: any) => {
      console.warn('📡 Socket.io خطأ الاتصال:', err.message);
    });

    socket.on('newActivity', (activity: any) => {
      setActivities(prev => [activity, ...prev].slice(0, 50));
      setUnreadCount(prev => prev + 1);
      playNotificationSound();
    });

    return () => {
      socket.disconnect();
      document.removeEventListener('click', unlock);
      document.removeEventListener('keydown', unlock);
    };
  }, [fetchActivities]);

  const handleMarkRead = async () => {
    try {
      await activityApi.markRead();
      setUnreadCount(0);
    } catch { /* ignore */ }
  };

  const handleOpenChange = (visible: boolean) => {
    setOpen(visible);
    if (visible && unreadCount > 0) {
      setTimeout(handleMarkRead, 500);
    }
  };

  const dropdownContent = (
    <div style={{
      width: 360,
      maxHeight: 480,
      overflow: 'auto',
      background: '#fff',
      borderRadius: 10,
      boxShadow: '0 6px 24px rgba(0,0,0,0.12)',
      border: '1px solid #f0f0f0',
    }}>
      <div style={{
        padding: '10px 14px',
        borderBottom: '1px solid #f0f0f0',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        background: '#fafafa',
        borderRadius: '10px 10px 0 0',
      }}>
        <span style={{ fontWeight: 600, fontSize: 14, color: '#2c3e50' }}>الإشعارات</span>
        {unreadCount > 0 && (
          <Button type="link" size="small" icon={<CheckOutlined />} onClick={handleMarkRead}>
            تعليم الكل كمقروء
          </Button>
        )}
      </div>

      {activities.length === 0 ? (
        <div style={{ padding: 32 }}>
          <Empty description="لا توجد إشعارات" image={Empty.PRESENTED_IMAGE_SIMPLE} />
        </div>
      ) : (
        <List
          size="small"
          dataSource={activities.slice(0, 30)}
          renderItem={(item: any) => (
            <List.Item style={{ padding: '8px 14px', borderBottom: '1px solid #f5f5f5' }}>
              <div style={{ width: '100%' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 2 }}>
                  <Tag color={actionColors[item.action]} style={{ fontSize: 11, margin: 0 }}>
                    {actionLabels[item.action] || item.action}
                  </Tag>
                  <span style={{ fontSize: 11, color: '#bbb' }}>
                    {item.createdAt ? dayjs(item.createdAt).format('HH:mm') : ''}
                  </span>
                </div>
                <div style={{ fontSize: 13, color: '#333', fontWeight: 500 }}>{item.description}</div>
                <div style={{ fontSize: 11, color: '#999' }}>
                  بواسطة {item.userName} · {item.moduleLabel}
                </div>
              </div>
            </List.Item>
          )}
        />
      )}
    </div>
  );

  return (
    <Dropdown
      dropdownRender={() => dropdownContent}
      trigger={['click']}
      open={open}
      onOpenChange={handleOpenChange}
      placement="bottomLeft"
    >
      <div style={{
        position: 'relative',
        cursor: 'pointer',
        padding: '6px',
        borderRadius: 8,
        display: 'flex',
        alignItems: 'center',
        transition: 'background 0.2s',
      }}
      onMouseEnter={(e) => e.currentTarget.style.background = 'rgba(0,0,0,0.04)'}
      onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
      >
        <Badge count={unreadCount} size="small" offset={[-2, 2]}>
          <BellOutlined style={{ fontSize: 18, color: '#2c3e50' }} />
        </Badge>
      </div>
    </Dropdown>
  );
}

import { useState, useEffect } from 'react';
import { Card, Table, Tag, Row, Col, Statistic, message, Segmented } from 'antd';
import { BellOutlined, CalendarOutlined, NotificationOutlined, CheckSquareOutlined } from '@ant-design/icons';
import api from '../api/client';
import { PageHeader } from '../components/PageHeader';

export default function Notifications() {
  const [notifications, setNotifications] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [filter, setFilter] = useState<string>('all');

  useEffect(() => {
    setLoading(true);
    api.get('/notifications').then(res => {
      setNotifications(res.data.data || res.data || []);
    }).catch(() => message.error('تعذر تحميل التنبيهات'))
    .finally(() => setLoading(false));
  }, []);

  const urgencyColors: Record<string, string> = {
    high: 'red',
    medium: 'orange',
    low: 'gold',
  };

  const urgencyLabels: Record<string, string> = {
    high: 'عاجل',
    medium: 'متوسط',
    low: 'منخفض',
  };

  const typeIcons: Record<string, React.ReactNode> = {
    session: <CalendarOutlined style={{ color: '#C9A227' }} />,
    announcement: <NotificationOutlined style={{ color: '#2980b9' }} />,
    task: <CheckSquareOutlined style={{ color: '#27ae60' }} />,
  };

  const typeLabels: Record<string, string> = {
    session: 'جلسة',
    announcement: 'إعلان',
    task: 'مهمة',
  };

  const highCount = notifications.filter(n => n.urgency === 'high').length;
  const mediumCount = notifications.filter(n => n.urgency === 'medium').length;
  const lowCount = notifications.filter(n => n.urgency === 'low').length;

  const sessionCount = notifications.filter(n => n.type === 'session').length;
  const announcementCount = notifications.filter(n => n.type === 'announcement').length;
  const taskCount = notifications.filter(n => n.type === 'task').length;

  const filteredNotifications = (filter === 'all'
    ? notifications
    : notifications.filter(n => n.type === filter)
  ).slice().sort((a, b) => {
    const courtA = a.courtName || '';
    const courtB = b.courtName || '';
    if (courtA !== courtB) return courtA.localeCompare(courtB, 'ar');
    const dateA = a.date ? a.date.split(' - ')[0] : '';
    const dateB = b.date ? b.date.split(' - ')[0] : '';
    return dateA.localeCompare(dateB);
  });

  const columns = [
    {
      title: 'النوع',
      dataIndex: 'type',
      render: (v: string) => (
        <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          {typeIcons[v] || <BellOutlined />}
          <span>{typeLabels[v] || v}</span>
        </span>
      ),
      width: 100,
    },
    { title: 'العنوان', dataIndex: 'title', ellipsis: true },
    { title: 'الموكل', dataIndex: 'customerName', render: (v: string) => v || '—', width: 100 },
    { title: 'المستلم', dataIndex: 'recipientName', render: (v: string) => v || '—', width: 100 },
    { title: 'الوصف', dataIndex: 'description', ellipsis: true },
    {
      title: 'تاريخ الجلسة القادمة',
      dataIndex: 'date',
      width: 110,
    },
    { title: 'رقم القضية', dataIndex: 'caseNumber', render: (v: string) => v || '—', width: 90 },
    { title: 'المحكمة', dataIndex: 'courtName', render: (v: string) => v || '—', width: 100 },
    {
      title: 'تاريخ التسليم',
      dataIndex: 'deliveryDate',
      render: (v: string) => v || '—',
      width: 110,
    },
    {
      title: 'تاريخ الاستلام',
      dataIndex: 'receiptDate',
      render: (v: string) => v || '—',
      width: 110,
    },
    {
      title: 'متبقي',
      dataIndex: 'daysLeft',
      render: (v: number) => v != null ? `${v} يوم` : '',
      width: 80,
    },
    {
      title: 'الأولوية',
      dataIndex: 'urgency',
      render: (v: string) => <Tag color={urgencyColors[v]}>{urgencyLabels[v] || v}</Tag>,
      width: 80,
    },
  ];

  return (
    <div>
      <PageHeader
        title="التنبيهات"
        subtitle="الجلسات القادمة والإعلانات والمهام التي تحتاج متابعة"
      />

      <Row gutter={[12, 12]} style={{ marginBottom: 10 }}>
        <Col xs={24} sm={8}>
          <Card size="small">
            <Statistic
              title="تنبيهات عاجلة"
              value={highCount}
              prefix={<BellOutlined />}
              valueStyle={{ color: '#c0392b' }}
            />
          </Card>
        </Col>
        <Col xs={24} sm={8}>
          <Card size="small">
            <Statistic
              title="تنبيهات متوسطة"
              value={mediumCount}
              valueStyle={{ color: '#e67e22' }}
            />
          </Card>
        </Col>
        <Col xs={24} sm={8}>
          <Card size="small">
            <Statistic
              title="تنبيهات منخفضة"
              value={lowCount}
              valueStyle={{ color: '#faad14' }}
            />
          </Card>
        </Col>
      </Row>

      <Card size="small">
        <div style={{ marginBottom: 12 }}>
          <Segmented
            value={filter}
            onChange={(v) => setFilter(v as string)}
            options={[
              { label: `الكل (${notifications.length})`, value: 'all' },
              { label: `جلسات (${sessionCount})`, value: 'session' },
              { label: `إعلانات (${announcementCount})`, value: 'announcement' },
              { label: `مهام (${taskCount})`, value: 'task' },
            ]}
          />
        </div>
        <Table
          columns={columns}
          dataSource={filteredNotifications}
          rowKey={(r) => r.id || r._id}
          loading={loading}
          size="small"
          pagination={{ pageSize: 10 }}
          locale={{ emptyText: 'لا توجد تنبيهات حالياً' }}
        />
      </Card>
    </div>
  );
}

import axios from 'axios';

const API_BASE_URL = 'http://localhost:3001/api';

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// إرفاق token في كل طلب
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('lexpro_token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// التعامل مع 401 (انتهاء الجلسة)
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      localStorage.removeItem('lexpro_token');
      localStorage.removeItem('lexpro_user');
      if (window.location.pathname !== '/login') {
        window.location.href = '/login';
      }
    }
    return Promise.reject(error);
  }
);

// مسارات الملفات
export const fileApi = {
  upload: (file: File) => {
    const formData = new FormData();
    formData.append('file', file);
    return api.post('/files/upload', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
    });
  },
  getUrl: (id: string) => `${API_BASE_URL}/files/${id}`,
};

// مسارات المصادقة
export const authApi = {
  login: (username: string, password: string) =>
    api.post('/auth/login', { username, password }),
  me: () => api.get('/auth/me'),
  updateProfile: (data: { name?: string; avatar?: string }) =>
    api.put('/auth/profile', data),
  changePassword: (currentPassword: string, newPassword: string) =>
    api.put('/auth/password', { currentPassword, newPassword }),
};

// مسارات المستخدمين
export const usersApi = {
  getAll: () => api.get('/users'),
  create: (data: any) => api.post('/users', data),
  update: (id: string, data: any) => api.put(`/users/${id}`, data),
  updatePermissions: (id: string, permissions: any[]) => api.put(`/users/${id}/permissions`, { permissions }),
  delete: (id: string) => api.delete(`/users/${id}`),
};

// مسارات سجل النشاط
export const activityApi = {
  getAll: () => api.get('/activity-logs'),
  markRead: () => api.put('/activity-logs/read'),
};

// مسارات الدردشة
export const chatApi = {
  getOnlineUsers: () => api.get('/auth/online-users'),
  getConversations: () => api.get('/messages/conversations'),
  getMessages: (userId: string) => api.get(`/messages/${userId}`),
  sendMessage: (receiverId: string, text: string) => api.post('/messages', { receiverId, text }),
};

// مسارات عامة CRUD
export function createCrudApi<T>(endpoint: string) {
  const path = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
  return {
    getAll: () => api.get(path),
    getById: (id: string) => api.get(`${path}/${id}`),
    create: (data: Partial<T>) => api.post(path, data),
    update: (id: string, data: Partial<T>) => api.put(`${path}/${id}`, data),
    delete: (id: string) => api.delete(`${path}/${id}`),
  };
}

export default api;

import { create } from 'zustand';

interface Permission {
  module: string;
  canView: boolean;
  canAdd: boolean;
  canEdit: boolean;
  canDelete: boolean;
}

interface AuthUser {
  id: string;
  name: string;
  username: string;
  role: string;
  permissions: Permission[];
}

interface AuthState {
  user: AuthUser | null;
  token: string | null;
  isAuthenticated: boolean;
  loading: boolean;
  setUser: (user: AuthUser | null) => void;
  setToken: (token: string | null) => void;
  logout: () => void;
  hasPermission: (module: string, action: 'view' | 'add' | 'edit' | 'delete') => boolean;
  canAccess: (path: string) => boolean;
}

export const useAuthStore = create<AuthState>((set, get) => ({
  user: (() => {
    try {
      const stored = localStorage.getItem('lexpro_user');
      return stored ? JSON.parse(stored) : null;
    } catch { return null; }
  })(),
  token: localStorage.getItem('lexpro_token'),
  isAuthenticated: !!localStorage.getItem('lexpro_token'),
  loading: false,

  setUser: (user) => {
    if (user) {
      localStorage.setItem('lexpro_user', JSON.stringify(user));
    } else {
      localStorage.removeItem('lexpro_user');
    }
    set({ user, isAuthenticated: !!user });
  },

  setToken: (token) => {
    if (token) {
      localStorage.setItem('lexpro_token', token);
    } else {
      localStorage.removeItem('lexpro_token');
    }
    set({ token, isAuthenticated: !!token });
  },

  logout: () => {
    localStorage.removeItem('lexpro_token');
    localStorage.removeItem('lexpro_user');
    set({ user: null, token: null, isAuthenticated: false });
  },

  hasPermission: (module, action) => {
    const { user } = get();
    if (!user) return false;
    if (user.role === 'admin') return true;
    const perm = user.permissions?.find(p => p.module === module);
    if (!perm) return false;
    if (action === 'view') return perm.canView;
    if (action === 'add') return perm.canAdd;
    if (action === 'edit') return perm.canEdit;
    if (action === 'delete') return perm.canDelete;
    return false;
  },

  canAccess: (path) => {
    const { user } = get();
    if (!user) return false;
    if (user.role === 'admin') return true;
    // خريطة المسارات إلى الوحدات
    const pathModuleMap: Record<string, string> = {
      '/': 'dashboard',
      '/customers': 'customers',
      '/cases': 'cases',
      '/sessions': 'sessions',
      '/announcements': 'announcements',
      '/tasks': 'tasks',
      '/fees': 'fees',
      '/expenses': 'expenses',
      '/templates': 'templates',
      '/notifications': 'notifications',
      '/customer-dossier': 'customers',
      '/court-dossier': 'cases',
      '/settings/backup': 'backup',
      '/settings/courts': 'settings',
      '/settings/case-types': 'settings',
      '/settings/announcement-types': 'settings',
      '/settings/lawyer-profile': 'settings',
      '/users': 'users',
    };
    const module = pathModuleMap[path];
    if (!module) return true;
    return get().hasPermission(module, 'view');
  },
}));

